  "narrative.10": "حكم على أمرين معًا: مدى تراكم الضغط والاهتمام نحو الذروة بطريقة متدرجة ومقنعة، ومدى مكافأة الذروة لما بُني نحوها دراميًا — لا يكفي بناء متقنٌ بذروة لا تليق به. وإذا اجتمع بناء متقن مع ذروة لا تكافئه — أو العكس — قُدِّرت الدرجة وفق قاعدة «الأبعاد المجمعة»: يُحدد البعد الأضعف؛ فإن كان جوهريًا حسم الدرجة نحوه، وإن كان التخلف محدودًا قُدِّرت الدرجة بدرجة واحدة وفق قاعدة «الأبعاد المجمعة» في القواعد العامة — بحسب أثر التخلف الملموس في وظيفة البطاقة والتجربة. لا يُشترط أن يكون التصعيد خطيًا؛ فالتموجات والتوقفات قد تكون مقصودة إذا كانت تخدم البناء.",
  "narrative.11": "حكم على جودة الإغلاق: معالجة نتائج ما بناه العمل، وملاءمة نوع الإغلاق لطبيعته، وإعطاؤه ما يستحقه من مساحة ووزن. لا يُشترط أن تكون النهاية مغلقة؛ فالنهاية المفتوحة أو التأملية قد تكون ممتازة إذا كانت مبررة ومناسبة. ولا تُخفض هذه البطاقة بسبب ضعف مكافأة الذروة وحده — فذلك يُسجّل في التصعيد، ولا يُخفض هنا إلا إذا وُجد خلل مستقل في الإغلاق نفسه.",
  "narrative.12": "حكم على مدى ملاءمة مستوى فاعلية الشخصيات — أو انفعاليتها المقصودة — لهدف العمل، لا على كون الشخصيات فاعلة بذاتها. لا يُشترط أن تكون كل شخصية فاعلة دائمًا؛ فبعض الأعمال تتطلب شخصية منفعلة (كعمل عن الضحية)، والتقييم يكون وفق ما يطلبه العمل.",
  "production.1": "حكم على ثبات الأسلوب البصري والإخراجي عبر العمل كله. لا يُشترط أن يكون الأسلوب واحدًا في كل مشهد؛ فالتنوع المقصود قد يكون ممتازًا إذا كان منسجمًا.",
  "production.2": "حكم على وظيفة البناء البصري في المشاهد عمومًا — التأطير والتكوين والحركة والتوزيع — في إيصال ما يحدث والتعبير عن معناه. البساطة المقصودة ليست عيبًا؛ فالتأطير الثابت الهادئ قد يكون ممتازًا إذا كان يناسب المشهد ويخدمه. أما الأثر المركّب لتنفيذ الذروات فيُقاس في اللحظات المحورية، وبناء اللقطة كعنصر يُقاس هنا في كل المشاهد بما فيها الذروات.",
